mapper.update:
update cynexus_appl_market.stock_selection_strategy_definition
   set name = #{strategy.name},
       description = #{strategy.description},
       version = version + 1,
       updated_at = now()
 where id = #{strategy.definitionId}
   and strategy_code = #{strategy.code}
   and strategy_type = 'USER_SCREENER'
   and tenant_id = #{tenantId}
   and owner_id = #{ownerId}
   and version = #{expectedDefinitionVersion}
   and status = 'ACTIVE'
   and deleted_at is null
